import{_ as i,K as r,a as l,c as o,b as a,k as t,q as d,ac as s}from"./chunks/framework.BSuaGltH.js";const v=JSON.parse('{"title":"国际象棋：检查威胁与减少失误","description":"复盘一个两回合将死，学会阅读棋谱、寻找更早的转折并安排十秒检查。","frontmatter":{"title":"国际象棋：检查威胁与减少失误","description":"复盘一个两回合将死，学会阅读棋谱、寻找更早的转折并安排十秒检查。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"棋类入门","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"国际象棋入门","summary":"复盘一个两回合将死，学会阅读棋谱、寻找更早的转折并安排十秒检查。","status":"active","related":[{"title":"国际象棋：棋子走法、特殊规则与胜负","link":"/life/personal/chess/international-chess/rules","kind":"棋类入门","scope":"general","audience":"general"},{"title":"国际象棋：双攻、牵制与串击","link":"/life/personal/chess/international-chess/tactics","kind":"棋类入门","scope":"general","audience":"general"},{"title":"国际象棋：开局原则与基础残局","link":"/life/personal/chess/international-chess/opening-endgame","kind":"棋类入门","scope":"general","audience":"general"}],"prev":{"text":"国际象棋：开局原则与基础残局","link":"/life/personal/chess/international-chess/opening-endgame"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"国际象棋：开局原则与基础残局","link":"/life/personal/chess/international-chess/opening-endgame"},"next":false},"headers":[],"relativePath":"life/personal/chess/international-chess/review.md","filePath":"life/personal/chess/international-chess/review.md"}'),p={name:"life/personal/chess/international-chess/review.md"},h={class:"chess-example"},c={class:"chess-figure"};function g(f,e,_,u,m,b){const n=r("ArticleImage");return l(),o("div",null,[e[1]||(e[1]=a("h1",{id:"国际象棋-检查威胁与减少失误",tabindex:"-1"},[t("国际象棋：检查威胁与减少失误 "),a("a",{class:"header-anchor",href:"#国际象棋-检查威胁与减少失误","aria-label":'Permalink to "国际象棋：检查威胁与减少失误"'},"​")],-1)),e[2]||(e[2]=a("p",null,"新手不必每盘都打开复杂的引擎变化。先问：我有没有漏看对方一步将军、一步吃子或一步将死？这些具体错误通常比开局选择更值得先改。",-1)),e[3]||(e[3]=a("h2",{id:"看懂这盘极短的棋",tabindex:"-1"},[t("看懂这盘极短的棋 "),a("a",{class:"header-anchor",href:"#看懂这盘极短的棋","aria-label":'Permalink to "看懂这盘极短的棋"'},"​")],-1)),a("div",h,[a("div",c,[a("p",null,[d(n,{src:"/images/chess/chess-review.svg",alt:"2...Qh4# · 两回合将死。黑后沿 h4–g3–f2 攻击 e1 白王。"})])]),e[0]||(e[0]=s(`<div class="chess-explanation"><p>从初始局面按下面顺序摆：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. f3   e5</span></span>
<span class="line"><span>2. g4   Qh4#</span></span></code></pre></div><p>白 f2 兵到 f3，黑 e7 兵到 e5；白 g2 兵到 g4，黑后 d8 到 h4，将死。这里的记录描述一条合法教学序列，不是建议双方采用的开局。</p><p>黑后 d8→h4 经过 e7、f6、g5；e7 已因黑兵前进而腾空，其他中间格也空，所以路线畅通。h4 后沿 g3、f2 攻击 e1 白王。白的 f 兵已经离开 f2，g 兵又离开 g2，使王前斜线暴露。</p><p>为什么不能挡？白方没有一步能把棋子合法放到 g3 或 f2；白王周围可去的格子被己方棋子占着或仍受攻击，也没有棋子能立即吃掉黑后。因此这是将死，不是普通将军。</p></div>`,1))]),e[4]||(e[4]=s('<h2 id="转折不只在最后一步" tabindex="-1">转折不只在最后一步 <a class="header-anchor" href="#转折不只在最后一步" aria-label="Permalink to &quot;转折不只在最后一步&quot;">​</a></h2><p>黑走 Qh4# 时，白已经没有机会补救。复盘应该回到白第二步 g4 之前。白若改走 e4，例如继续 2...Nc6，棋局就不会按同一条路线立刻结束。这不是说 e4 是唯一好棋，而是说明 g4 不是强制选择。</p><p>写“不能走 f 兵”仍然太绝对。某些布局确实走 f 兵；本例的关键是连续移动王翼兵、开放通向王的斜线，却没有发展棋子或确认对手威胁。</p><h2 id="落子前的十秒检查" tabindex="-1">落子前的十秒检查 <a class="header-anchor" href="#落子前的十秒检查" aria-label="Permalink to &quot;落子前的十秒检查&quot;">​</a></h2><p>先看自己是否被将军；再列对手下一步能给出的将军、直接吃子、一步杀棋；最后检查自己的落点是否被保护。慢棋时把这三个问题真正回答一遍，不只是默念“检查过了”。</p><p>如果走后才发现丢子，不要用一次没有算清的进攻去补偿。先把局面稳定下来，减少第二次失误；训练中可以摆回去分析，但正式对局不能自行悔棋。</p><h2 id="怎样记录一次复盘" tabindex="-1">怎样记录一次复盘 <a class="header-anchor" href="#怎样记录一次复盘" aria-label="Permalink to &quot;怎样记录一次复盘&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>示例</th></tr></thead><tbody><tr><td>原想法</td><td>走 g4，想把兵往前推</td></tr><tr><td>忽略的信息</td><td>黑后到 h4 的路线已打开</td></tr><tr><td>实际结果</td><td>e1 王沿 h4–g3–f2 斜线被将死</td></tr><tr><td>可替代着</td><td>先走 e4 等发展着，再检查对手回应</td></tr><tr><td>下次动作</td><td>推王翼兵前，检查指向王的对角线</td></tr></tbody></table><p>使用引擎时，先写自己的解释，再看它建议什么。一个“+3”或“-5”评分不等于原因。只有能指出哪个格子、哪条线路或哪个无保护子，才算理解。</p><h2 id="练习与答案" tabindex="-1">练习与答案 <a class="header-anchor" href="#练习与答案" aria-label="Permalink to &quot;练习与答案&quot;">​</a></h2><ol><li>如果白兵仍在 f2，黑后 h4 是否沿同一路线直接将军 e1？<strong>不是。</strong> f2 兵挡在后与王之间；可能攻击兵，但不能隔子攻击王。</li><li>输掉后应不应该把整套开局换掉？<strong>不必。</strong> 本例先修复威胁检查，问题比开局名称更具体。</li><li>复盘发现一个候选着，怎样证明它能避免原先的失败？<strong>重新摆入局面，让对方尝试原来的将军或杀棋，检查线路与合法回应。</strong></li></ol><p>先连续三盘执行同一个检查习惯，再增加新目标。规则背景：<a href="https://handbook.fide.com/chapter/E012023" target="_blank" rel="noopener noreferrer">FIDE 官方手册</a>；上述短局与练习用来解释基本威胁识别。</p>',12))])}const x=i(p,[["render",g]]);export{v as __pageData,x as default};
